function auditTiming(files, config, harnessFiles, fullSourceLeaves, fullHarnessLeaves) {
 const hash=eval("("+load("runtime_fixture_sha256_function_source")+")"), utf8=eval("("+load("four_partition_utf8_source")+")");
 const sha1=eval("("+load("four_partition_sha1_source")+")"),merkle=eval("("+load("four_partition_merkle_source")+")");
 const require=(value,label)=>{if(!value)throw Error(label);};
 const stable=v=>v&&typeof v==="object"?(Array.isArray(v)?v.map(stable):Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])]))):v;
 const same=(a,b)=>JSON.stringify(stable(a))===JSON.stringify(stable(b));
 const json=n=>{require(files[n],"Missing "+n);return JSON.parse(files[n].text);};
 const identity=(file,pin)=>require(file.bytes===pin.bytes&&file.sha256===pin.sha256,"Identity mismatch");
 const gitEntries=map=>Object.entries(map).map(([path,row])=>({path,mode:row.mode,type:"blob",sha:row.git_blob}));
 const outcome=json("job-outcome.json"), steps=json("steps.json"), commands=json("commands.json"), manifest=json("artifact-manifest.json");
 require(Object.keys(files).length===53,"Original member count");
 require(Object.keys(manifest).length===51,"Internal manifest count");
 require(same(Object.keys(files).filter(n=>!Object.hasOwn(manifest,n)).sort(),["artifact-manifest.json","job-outcome.json"]),"Manifest exclusions");
 for(const [name,pin]of Object.entries(manifest))identity(files[name],pin);
 require(outcome.passed===true&&outcome.error===null&&outcome.source_unchanged===true&&outcome.qualification_complete===false,"Outcome");
 require(outcome.harness_sha==="f50dac982e82cc1a5420f103d83f7b79b19d7849"&&outcome.source_sha===config.source_sha&&outcome.source_tree===config.source_tree&&outcome.run_id==="35465099173"&&outcome.run_attempt==="1","Outcome source/run");
 require(same(outcome.steps,steps)&&same(steps,commands)&&steps.length===19,"Commands exact");
 const names=["source-admission-before-environment","uv-version","create-validation-environment","frozen-project-install","dependency-compatibility","environment-before"];
 for(let p=1;p<=5;p++)for(const arm of config.pair_order[p-1])names.push("pair-"+String(p).padStart(2,"0")+"-"+arm);
 names.push("container-diagnostic-baseline","container-diagnostic-candidate","environment-after");
 require(same(steps.map(s=>s.name),names)&&new Set(names).size===19,"Command order");
 const commandRows=[];
 for(const step of steps){
  require(step.passed===true&&step.returncode===0&&step.timed_out===false,"Original command failure");
  identity(files[step.name+".log"],{bytes:step.log_bytes,sha256:step.log_sha256});
  const c=step.group_cleanup;require(c.passed===true&&c.no_live_members_in_original_group===true&&c.errors.length===0,"Group cleanup");
  require(c.pgid===step.pid&&step.leader_identity.pid===step.pid&&step.leader_identity.uid===1001,"Original group identity");
  require(c.snapshots.length>=1&&c.snapshots.every(s=>s.inspection_errors.length===0&&s.live.length===0),"Group post-observation");
  if(step.name.startsWith("pair-")||step.name.startsWith("container-")){
   require(same(step.command.slice(1,4),["-P","-s","-B"])&&step.timeout_seconds===120,"Measured command flags/bounds");
  }
  commandRows.push({name:step.name,pid:step.pid,returncode:step.returncode,timed_out:step.timed_out,wall_seconds:step.wall_seconds,timeout_seconds:step.timeout_seconds,owned_group_retired:true,log_sha256:step.log_sha256});
 }
 require(outcome.all_original_owned_groups_retired===true&&outcome.no_complete_descendant_cleanup_certificate===true,"Cleanup scope");
 const source=json("source-before.json"), after=json("source-after.json");
 require(files["source-before.json"].text===files["source-after.json"].text,"Source before/after bytes");
 require(source.source_sha===config.source_sha&&source.source_tree===config.source_tree&&source.harness_sha===outcome.harness_sha,"Source map identity");
 require(Object.keys(source.files).length===4623&&Object.keys(source.baseline_files).length===4622&&Object.keys(source.harness_files).length===19,"Map counts");
 const norm=rows=>rows.map(r=>({path:r.path,mode:r.mode,sha:r.sha||r.git_blob})).sort((a,b)=>a.path.localeCompare(b.path));
 require(same(norm(gitEntries(source.files)),norm(fullSourceLeaves)),"All source Git leaves");
 for(const f of harnessFiles){identity(source.harness_files[f.path],f);require(hash(f.content)===f.sha256&&utf8(f.content).length===f.bytes&&sha1(utf8("blob "+f.bytes+"\0").concat(utf8(f.content)))===f.git_blob,"Exact independently retained harness body");}
 const combined=[...gitEntries(source.files),...harnessFiles.map(f=>({path:f.path,mode:"100644",type:"blob",sha:f.git_blob}))];
 require(same(norm(combined),norm(fullHarnessLeaves)),"All harness Git leaves");
 const trees={source:merkle(gitEntries(source.files),sha1,utf8),baseline:merkle(gitEntries(source.baseline_files),sha1,utf8),harness:merkle(combined,sha1,utf8)};
 require(trees.source===config.source_tree&&trees.baseline===config.baseline.tree&&trees.harness==="7c14f249d9e70370117521290d1a7451020c35e6","Recomputed source trees");
 for(const f of harnessFiles)identity(source.harness_files[f.path],f);
 for(const [path,pin]of Object.entries(config.candidate_files))require(same(source.files[path],pin),"Candidate source pin");
 for(const [path,pin]of Object.entries(config.baseline_input_files))require(same(source.baseline_files[path],pin),"Baseline source pin");
 const env=json("environment-before.json");
 require(files["environment-before.json"].text===files["environment-after.json"].text,"Environment exact before/after");
 require(env.installed_count===69&&same(env.installed_versions,config.installed_versions)&&env.all_versions_match_frozen_lock===true&&env.prior_69_reference_matches===true,"Frozen69 environment");
 require(env.executable.startsWith("/tmp/pr2974-rsp130-join-timing-35465099173-1/")&&env.platform==="linux","Owned environment");
 for(const launcher of Object.values(env.launchers))require(launcher.uid===1001&&launcher.mode==="0o755"&&launcher.sha256==="edcdaf07e49bb241cbccb0f18fdb2c8f2e6e1be36a583fce9fc703894d814238","Launcher");
 const syntax=json("harness-syntax.json");require(syntax.passed===true&&syntax.project_imports.length===0&&syntax.files.length===10,"Harness syntax");
 for(const row of syntax.files){const pin=harnessFiles.find(f=>f.path==="ci/pr2974_rsp130_join_timing/"+row.name);require(pin,"Syntax file");identity(row,pin);}
 const contract=json("source-contract.json");require(contract.passed===true&&contract.source_sha===config.source_sha&&contract.source_tree===config.source_tree&&contract.project_imports.length===0,"Source contract");
 require(contract.caller.complete_signature_body_reconstructed&&contract.caller.all_statements_before_after_join_equal&&contract.caller.join_after_original_batch_callback&&contract.caller.original_inline_fallback_ast_equal,"Caller source proof");
 require(contract.format_bridges.length===3,"Formatter bridge count");
 for(const bridge of contract.format_bridges){require(bridge.passed===true&&bridge.full_ast_equal_including_type_comments_and_type_ignore_line_fields&&bridge.canonical_tokens_equal&&bridge.comments_and_statement_token_anchors_equal,"Actual full strict bridge");require(bridge.after_sha256===source.files[bridge.path].sha256,"Bridge source");const raw=json("final-format-bridges/"+bridge.path+".json");require(raw.passed&&raw.after_sha256===bridge.after_sha256,"Full bridge file");}
 const admitted=json("admitted-evidence.json");
 require(same(admitted.functional,config.functional_admission)&&same(admitted.operations,config.operation_admission),"Prior admission pins");
 require(admitted.historical_functional_cases===45&&admitted.actual_operation_cells===6&&admitted.original_failure_preserved===true&&admitted.historical_functional_overall_run==="failure"&&admitted.operations_overall_passed===true,"Prior attribution");
 identity(files["original-functional-terminal.json"],config.functional_admission);identity(files["operation-admission.json"],config.operation_admission);
 require(files["original-functional-terminal.json"].text===load("rsp130_finite_first_terminal").text,"Exact previous functional terminal");
 require(files["operation-admission.json"].text===load("rsp130_operations_first_terminal").text,"Exact previous operations terminal");
 for(const name of ["measurement-proposal.json","interpreter-source.json"]){const pin=harnessFiles.find(f=>f.path.endsWith("/"+name));identity(files[name],pin);require(files[name].text===pin.content,"Exact fixed report");}
 const result=json("measurement-results.json");require(result.errors.length===0&&result.arm_reports.length===10&&result.diagnostic_reports.length===2&&result.pairs.length===5,"Measurement report population");
 require(result.optimization_selected===false&&result.production_threshold_selected===null&&result.whole_workload_requirement_satisfied===false&&result.qualification_complete===false,"No selection");
 const modes=["cold_alias","cold_independent","warm_independent"], summaries={},armAudit=[];
 const expectedIdentity=cell=>{
  const distinct=cell.shape==="duplicate_snapshot_ids"?Math.max(1,Math.floor(cell.S/2)):cell.S;
  const visits=Array.from({length:cell.S},(_,i)=>i%distinct), sourceCount=cell.shape==="repeated_source_references"&&cell.P?Math.max(1,Math.floor(cell.P/4)):cell.P;
  const unmatched=cell.S===0||cell.shape==="unmatched_source_keys";
  const counts=new Map();
  for(let i=0;i<cell.P;i++){const base=cell.shape==="repeated_source_references"?i%sourceCount:i;const ordinal=unmatched?distinct+10000+base:base%distinct;counts.set(ordinal,(counts.get(ordinal)||0)+1);}
  const unique=[...new Set(visits)];
  return {identity:{result_keys:unique.length,returned_source_occurrences:unique.reduce((n,k)=>n+(counts.get(k)||0),0),snapshot_visit_match_occurrences:visits.reduce((n,k)=>n+(counts.get(k)||0),0)},grouped:counts.size};
 };
 const outcomes=config.cells.map(expectedIdentity);
 const verifyOrigins=(report,arm)=>{
  require(same(report.product_origins_before,report.product_origins_after)&&report.product_origins_unchanged===true,"Product origins unchanged");
  const map=arm==="baseline"?source.baseline_files:source.files;
  for(const pin of Object.values(report.product_origins_after))identity(pin,map["src/"+pin.path]);
  require(same(report.before,report.after)&&report.sources_unchanged===true,"Watched source unchanged");
  for(const [path,pin]of Object.entries(report.before)){
   let relative,map;
   if(path.includes("/baseline/")){relative=path.split("/baseline/")[1];map=source.baseline_files;}
   else if(path.includes("/source/")){relative=path.split("/source/")[1];map=source.files;}
   else if(path.includes("/harness/")){relative=path.split("/harness/")[1];map=source.harness_files;}
   else throw Error("Unadmitted watched origin");
   identity(pin,map[relative]);
  }
 };
 const metrics=values=>{const s=[...values].sort((a,b)=>a-b);return {minimum:s[0],maximum:s.at(-1),median:(s[9]+s[10])/2,p95_nearest_rank:s[18]};};
 const settings=[];
 for(let pair=1;pair<=5;pair++)for(const arm of config.pair_order[pair-1]){
  const name="pair-"+String(pair).padStart(2,"0")+"-"+arm+".json", report=json(name);
  const pin=result.arm_reports.find(r=>r.path===name);require(pin&&pin.actual_passed===true,"Arm output");identity(files[name],pin);
  require(report.schema==="pr2974-rsp130-join-micro-arm.v1"&&report.passed===true&&report.pair===pair&&report.arm===arm&&!report.error&&!report.final_observation_error,"Arm identity");
  require(report.samples.length===1080&&report.optimization_selected===false&&report.qualification_complete===false,"Arm scope");
  verifyOrigins(report,arm);
  require(report.trace_after_is_none&&report.profile_after_is_none&&report.allocation_trace_after_is_none&&report.gc_enabled===true,"Uninstrumented timing");
  require(report.python.executable===env.executable&&report.python.executable_digest.sha256===env.launchers.python.sha256&&report.python.executable_digest.bytes===17752,"Actual interpreter");
  const set=report.runtime_settings,seed=String(config.pair_hash_seeds[pair-1]);
  require(report.hash_seed===seed&&same(set.python_environment,{PYTHONHASHSEED:seed}),"Actual seed");
  require(same(set.python_flags,{dont_write_bytecode:1,hash_randomization:1,ignore_environment:0,isolated:0,no_user_site:1,optimize:0,safe_path:true}),"Python flags");
  require(set.hash_sentinels.length===2&&set.hash_sentinels.every(s=>typeof s==="string"&&/^-?\d+$/.test(s)),"Sentinels remain exact decimal strings");
  require(!set.startup_sys_path.includes("")&&!set.startup_sys_path.includes("/tmp/pr2974-rsp130-join-timing-35465099173-1"),"Safe import path");
  for(const info of Object.values(report.clock_info))require(info.monotonic===true&&info.adjustable===false&&info.resolution>0,"Clock contract");
  const own=[];
  let k=0;
  for(let cell=0;cell<18;cell++)for(const mode of modes){
   const rows=report.samples.slice(k,k+20);k+=20;
   for(let n=0;n<20;n++){const row=rows[n];require(row.cell_index===cell&&row.mode===mode&&row.sample===n&&row.result_verified_after_stop===true&&same(row.result_identity,outcomes[cell].identity),"Exact sample/independent ordinal outcome");for(const metric of ["wall_ns","process_cpu_ns"])require(Number.isSafeInteger(row[metric])&&row[metric]>=0,"Raw timing integer");}
   own.push({cell_index:cell,mode,metrics:{wall_ns:metrics(rows.map(r=>r.wall_ns)),process_cpu_ns:metrics(rows.map(r=>r.process_cpu_ns))}});
  }
  summaries[pair+":"+arm]=own;settings.push({pair,arm,hash_seed:seed,...set});
  armAudit.push({pair,arm,path:name,bytes:files[name].bytes,sha256:files[name].sha256,samples:1080,all_ordinal_outcomes_exact:true,source_origins:Object.keys(report.product_origins_after).length,interpreter:report.python,clock_info:report.clock_info,cpu_affinity:report.cpu_affinity});
 }
 const ratioRows=[];
 for(let pair=1;pair<=5;pair++){
  const a=settings.find(s=>s.pair===pair&&s.arm==="baseline"),b=settings.find(s=>s.pair===pair&&s.arm==="candidate");require(same(a.hash_sentinels,b.hash_sentinels)&&same(a.python_flags,b.python_flags),"Pair seed equivalence");
  const actual=result.pairs[pair-1];require(actual.pair===pair&&actual.complete===true&&actual.rows.length===54,"Pair complete");
  for(let k=0;k<54;k++){
   const left=summaries[pair+":baseline"][k],right=summaries[pair+":candidate"][k],row=actual.rows[k];
   require(row.cell_index===left.cell_index&&row.mode===left.mode&&same(row.baseline,left.metrics)&&same(row.candidate,right.metrics),"Independent raw statistic mismatch");
   for(const metric of ["wall_ns","process_cpu_ns"])for(const estimator of ["median","p95_nearest_rank"]){const denominator=left.metrics[metric][estimator],expected=denominator?right.metrics[metric][estimator]/denominator:null;require(row.candidate_over_baseline[metric][estimator]===expected,"Ratio mismatch");}
   ratioRows.push({pair,...row});
  }
 }
 const diagnostics=[];
 for(const arm of ["baseline","candidate"]){
  const name="container-diagnostic-"+arm+".json",report=json(name),pin=result.diagnostic_reports.find(r=>r.path===name);identity(files[name],pin);
  require(report.passed===true&&pin.actual_passed===true&&report.arm===arm&&report.observations.length===54&&report.timing_samples===0,"Separate diagnostics");
  require(report.peak_memory_bytes===null&&report.process_rss_bytes===null&&report.physical_bytes===null&&report.optimization_selected===false&&report.qualification_complete===false,"Diagnostic limits");
  require(report.trace_after_is_none&&report.profile_after_is_none,"Diagnostic cleanup");
  verifyOrigins(report,arm);
  let k=0;
  for(let c=0;c<18;c++)for(const mode of modes){
   const row=report.observations[k++],actual=row.actual;
   require(row.cell_index===c&&row.mode===mode&&same(row.result_identity,outcomes[c].identity),"Diagnostic ordinal identity");
   require(actual.target_calls===1&&actual.target_returns===1&&actual.result_keys===outcomes[c].identity.result_keys&&actual.returned_tuple_occurrences===outcomes[c].identity.returned_source_occurrences,"Actual return-frame counts");
   if(arm==="candidate")require(actual.candidate_temporary_groups_observed===true&&actual.snapshot_id_entries===config.cells[c].S&&actual.source_id_entries===config.cells[c].P&&actual.grouped_source_occurrences===config.cells[c].P&&actual.grouped_keys===outcomes[c].grouped,"Actual temporary groups");
   else require(actual.candidate_temporary_groups_observed===false,"Baseline scope");
   for(const [name,value]of Object.entries(actual))if(name.endsWith("_bytes"))require(Number.isSafeInteger(value)&&value>=0,"Shallow container size");
  }
  diagnostics.push({arm,path:name,sha256:files[name].sha256,observations:report.observations,source_origins:Object.keys(report.product_origins_after).length,target:report.target});
 }
 return {schema:"pr2974_rsp130_timing_original_data_audit_v1",passed:true,command_count:19,commands:commandRows,source_trees:trees,source_files:4623,baseline_files:4622,harness_files:19,environment:{sha256:files["environment-before.json"].sha256,installed_versions:env.installed_versions,dependency_files:Object.keys(env.dependency_files).length,launchers:env.launchers,executable:env.executable},frame_and_file_scope:{original_files:53,internal_manifest_members:51,original_bytes:Object.values(files).reduce((n,f)=>n+f.bytes,0)},source_contract:contract,actual_prerequisites:admitted,fresh_functional_bodies:0,fresh_opcode_cells:0,arms:armAudit,timed_joins:10800,pairs:5,settings,independently_recomputed_ratio_rows:ratioRows,diagnostics,all_original_outcomes_and_raw_samples_retained:true,optimization_selected:false,whole_workload_requirement_satisfied:false,qualification_complete:false};
}
